def test_post_merge_recovery_seed_materializes_one_verified_gitlink(
    tmp_path,
):
    child_source = tmp_path / "child-source"
    child_source.mkdir()
    _git(child_source, "init")
    _git(child_source, "checkout", "-b", "main")
    _git(child_source, "config", "user.name", "Test User")
    _git(child_source, "config", "user.email", "test@example.invalid")
    (child_source / "contract.txt").write_text(
        "baseline\n",
        encoding="utf-8",
    )
    _git(child_source, "add", "contract.txt")
    _git(child_source, "commit", "-m", "child baseline")

    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    _git(repo, "checkout", "-b", "main")
    _git(repo, "config", "user.name", "Test User")
    _git(repo, "config", "user.email", "test@example.invalid")
    (repo / "todo.md").write_text("# Todos\n", encoding="utf-8")
    _git(
        repo,
        "-c",
        "protocol.file.allow=always",
        "submodule",
        "add",
        str(child_source),
        "external/child",
    )
    _git(repo, "add", ".gitmodules", "external/child", "todo.md")
    _git(repo, "commit", "-m", "root baseline")
    target_commit = _git(repo, "rev-parse", "HEAD")

    child = repo / "external" / "child"
    _git(child, "config", "user.name", "Test User")
    _git(child, "config", "user.email", "test@example.invalid")
    (child / "contract.txt").write_text(
        "reviewed repair\n",
        encoding="utf-8",
    )
    _git(child, "add", "contract.txt")
    _git(child, "commit", "-m", "reviewed child repair")
    child_commit = _git(child, "rev-parse", "HEAD")
    status_before = _git(repo, "status", "--porcelain=v1")

    daemon = TodoImplementationDaemon(
        todo_path=repo / "todo.md",
        state_path=repo / "state" / "task_state.json",
        strategy_path=repo / "state" / "strategy.json",
        events_path=repo / "state" / "events.jsonl",
        repo_root=repo,
        merge_target_branch="main",
        worktree_submodule_paths=["external/child"],
    )
    task = PortalTask(
        task_id="ACCEL-001",
        title="Recover reviewed child repair",
        status="todo",
        completion="manual",
        priority="P0",
        track="ops",
        outputs=["external/child/contract.txt"],
    )

    fields = daemon._materialize_post_merge_recovery_seed(
        task=task,
        recovery_seed_submodule_path="external/child",
        recovery_seed_submodule_commit=child_commit,
    )

    assert fields["recovery_seed_submodule_commit"] == child_commit
    seed_commit = fields["recovery_seed_ref"]
    child_retention_ref = (
        daemon._post_merge_recovery_seed_child_ref_name(
            task,
            "external/child",
            child_commit,
        )
    )
    assert _git(child, "rev-parse", child_retention_ref) == child_commit
    assert _git(repo, "rev-parse", f"{seed_commit}^") == target_commit
    assert _git(repo, "status", "--porcelain=v1") == status_before
    authority = daemon._post_merge_correction_authority_descriptor(
        authority_kind="repair_grant",
        authority_id="grant-1",
        authority_event_sequence=1,
        task=task,
        attempt=5,
        extra=fields,
    )
    plan = daemon._prior_attempt_seed_plan(
        state=TodoTaskState(),
        attempt=5,
        task=task,
        post_merge_correction_authority=authority,
        expected_target_commit=target_commit,
    )
    assert plan["recovery_seed_present"] is True
    assert plan["recovery_seed_valid"] is True
    assert plan["seed_ref"] == seed_commit
    assert plan["baseline_ref"] == target_commit
    assert plan["reason"] == "post_merge_recovery_seed"


def test_post_merge_recovery_seed_validator_only_allows_integrated_target_opt_in(
    tmp_path,
):
    repo, child = _seed_parent_with_submodule(tmp_path)
    baseline = _git(repo, "rev-parse", "main")
    (child / "reviewed-recovery.txt").write_text(
        "reviewed recovery\n",
        encoding="utf-8",
    )
    _git(child, "add", "reviewed-recovery.txt")
    _git(child, "commit", "-m", "reviewed recovery child")
    child_commit = _git(child, "rev-parse", "HEAD")
    daemon = TodoImplementationDaemon(
        todo_path=repo / "todo.md",
        state_path=repo / "state" / "task_state.json",
        strategy_path=repo / "state" / "strategy.json",
        events_path=repo / "state" / "events.jsonl",
        repo_root=repo,
        merge_target_branch="main",
        worktree_submodule_paths=["libs/child"],
    )
    task = PortalTask(
        task_id="REF-049",
        title="Retry one integrated recovery seed",
        status="todo",
        completion="manual",
        priority="P0",
        track="logic",
        outputs=["libs/child/reviewed-recovery.txt"],
    )
    seed = daemon._materialize_post_merge_recovery_seed(
        task=task,
        recovery_seed_submodule_path="libs/child",
        recovery_seed_submodule_commit=child_commit,
    )
    seed_commit = seed["recovery_seed_ref"]
    seed_tree = _git(repo, "rev-parse", f"{seed_commit}^{{tree}}")
    merge = subprocess.run(
        [
            "git",
            "commit-tree",
            seed_tree,
            "-p",
            baseline,
            "-p",
            seed_commit,
        ],
        cwd=repo,
        input="integrate reviewed recovery seed\n",
        text=True,
        capture_output=True,
        check=False,
    )
    assert merge.returncode == 0, merge.stderr
    integrated_target = merge.stdout.strip()
    _git(
        repo,
        "update-ref",
        "refs/heads/main",
        integrated_target,
        baseline,
    )

    strict, strict_error = daemon._validated_post_merge_recovery_seed_commit(
        task=task,
        **seed,
        expected_target_commit=baseline,
    )
    integrated, integrated_error = (
        daemon._validated_post_merge_recovery_seed_commit(
            task=task,
            **seed,
            expected_target_commit=baseline,
            allow_already_integrated_target=True,
        )
    )

    assert strict == {}
    assert strict_error == "recovery_seed_target_changed"
    assert integrated_error == ""
    assert integrated["recovery_seed_parent_commit"] == baseline
    assert integrated["recovery_seed_target_already_integrated"] is True
    assert (
        integrated["recovery_seed_observed_target_commit"]
        == integrated_target
    )
    assert (
        integrated["recovery_seed_observed_target_gitlink"]
        == child_commit
    )

    baseline_tree = _git(repo, "rev-parse", f"{baseline}^{{tree}}")
    divergent = subprocess.run(
        ["git", "commit-tree", baseline_tree, "-p", baseline],
        cwd=repo,
        input="divergent target\n",
        text=True,
        capture_output=True,
        check=False,
    )
    assert divergent.returncode == 0, divergent.stderr
    divergent_target = divergent.stdout.strip()
    _git(
        repo,
        "update-ref",
        "refs/heads/main",
        divergent_target,
        integrated_target,
    )

    rejected, rejected_error = (
        daemon._validated_post_merge_recovery_seed_commit(
            task=task,
            **seed,
            expected_target_commit=baseline,
            allow_already_integrated_target=True,
        )
    )

    assert rejected == {}
    assert rejected_error == "recovery_seed_integrated_target_mismatch"


def test_explicit_legacy_high_water_migration_is_exact_and_idempotent(
    post_merge_denial_case_factory,
    monkeypatch,
):
    case = post_merge_denial_case_factory()
    task_binding_id = (
        post_merge_review_module.post_merge_task_binding_id(case.task)
    )
    common = {
        "task_id": case.task.task_id,
        "canonical_task_key": case.identity.canonical_task_key,
        "canonical_task_cid": case.identity.canonical_task_cid,
        "board_namespace": case.identity.board_namespace,
        "task_binding_id": task_binding_id,
    }
    attempt_events = []

    def record_failed_attempt(attempt, *, recovered=False):
        legacy_started_identity = dict(common)
        # Pre-upgrade starts did not carry the board-blob binding. The
        # migration may accept that one missing field only after every other
        # immutable identity coordinate matches the permanent denial.
        legacy_started_identity.pop("task_binding_id")
        started = case.daemon._record_event(
            "implementation_started",
            {
                **legacy_started_identity,
                "attempt": attempt,
                "branch": f"implementation/rev-001-attempt-{attempt}",
                "baseline_ref": case.merge_commit,
                "command": ["test-provider", "run"],
            },
            enrich=False,
        )
        if recovered:
            terminal = case.daemon._record_event(
                "implementation_state_recovered",
                {
                    **common,
                    "attempt": attempt,
                    "branch": (
                        f"implementation/rev-001-attempt-{attempt}"
                    ),
                    "reason": "inflight_process_missing",
                    "attempt_recovery": {
                        "task_id": case.task.task_id,
                        "canonical_task_key": (
                            case.identity.canonical_task_key
                        ),
                        "canonical_task_cid": (
                            case.identity.canonical_task_cid
                        ),
                        "consumed": False,
                        "attempt": attempt,
                        "previous_display_count": attempt,
                        "previous_cid_count": attempt,
                    },
                },
                enrich=False,
            )
        else:
            terminal_identity = dict(common)
            if attempt == 2:
                # The oldest pre-upgrade failure omitted the binding on both
                # its start and terminal events.
                terminal_identity.pop("task_binding_id")
            terminal = case.daemon._record_event(
                "implementation_finished",
                {
                    **terminal_identity,
                    "attempt": attempt,
                    "branch": (
                        f"implementation/rev-001-attempt-{attempt}"
                    ),
                    "baseline_ref": case.merge_commit,
                    "implementation_commit": "",
                    "returncode": 78,
                    "attempt_consumed": True,
                    "validation_result": {
                        "attempted": True,
                        "passed": False,
                        "returncode": 78,
                        "reason": "proposal_gate_failed",
                    },
                    "merge_result": {
                        "attempted": False,
                        "merged": False,
                        "reason": "not_attempted",
                    },
                },
                enrich=False,
            )
        attempt_events.append(
            {
                "attempt": attempt,
                "started_event_id": started["event_id"],
                "started_event_sequence": started["sequence"],
                "terminal_event_id": terminal["event_id"],
                "terminal_event_sequence": terminal["sequence"],
                "terminal_event_type": terminal["type"],
            }
        )
        return terminal

    first_terminal = record_failed_attempt(2)
    case.daemon._migrate_post_merge_review_consumptions_from_strict_ledger(
        case.daemon.events_path
    )
    record_failed_attempt(3)
    record_failed_attempt(4, recovered=True)
    denials = case.queue.verified_post_merge_review_denials()
    consumptions = (
        case.queue.verified_post_merge_review_denial_consumptions()
    )
    assert len(denials) == 1
    assert len(consumptions) == 1
    assert consumptions[0]["consuming_event_id"] == (
        first_terminal["event_id"]
    )

    state = TodoTaskState.load(case.daemon.state_path)
    state.task_identities[case.task.task_id] = case.identity.to_dict()
    state.implementation_attempts[case.task.task_id] = 4
    state.implementation_attempts_by_cid[
        case.identity.canonical_task_cid
    ] = 4
    state.save(case.daemon.state_path)
    case.daemon.task_queue.set_attempt_count(
        case.identity.canonical_task_cid,
        4,
    )
    case.daemon.task_queue.save()
    seed = {
        "recovery_seed_ref": "a" * 40,
        "recovery_seed_tree_id": f"git-tree:{'b' * 40}",
        "recovery_seed_submodule_path": "external/ipfs_datasets",
        "recovery_seed_submodule_commit": "c" * 40,
    }
    materializations = []
    contender_observations = []
    supervisor_contender_observations = []
    published_lease_ids = []
    advance_target_during_first_materialization = {"pending": True}
    replace_lock_during_validation = {"pending": False}
    replacement_lock_metadata = {}
    checkout_supervisor = TodoImplementationSupervisor(
        TodoSupervisorConfig(
            todo_path=case.daemon.todo_path,
            state_path=case.daemon.state_path,
            strategy_path=case.daemon.strategy_path,
            events_path=case.daemon.events_path,
            state_dir=case.daemon.state_path.parent,
            repo_root=case.repo,
        )
    )

    def materialize(**kwargs):
        merge_lock_path = case.daemon._repo_merge_lock_path()
        assert merge_lock_path.exists()
        published_lock = json.loads(
            merge_lock_path.read_text(encoding="utf-8")
        )
        assert published_lock["state_lifecycle_independent"] is True
        assert published_lock["lease_id"]
        published_lease_ids.append(published_lock["lease_id"])
        contender_observations.append(
            case.daemon._try_acquire_lock(
                merge_lock_path,
                lock_kind="merge",
                owner_active=case.daemon._merge_lock_owner_is_active,
            )
        )
        contender_fd, contender_reason, contender_owner = (
            contender_observations[-1]
        )
        assert contender_fd is None
        assert contender_reason == "lock_exists"
        assert contender_owner == published_lock
        supervisor_contender_metadata = (
            checkout_supervisor
            ._build_published_checkout_lock_metadata(
                branch="supervisor-contender",
                operation="test_supervisor_contender",
            )
        )
        supervisor_contender_observations.append(
            checkout_supervisor
            ._try_acquire_published_checkout_lock(
                merge_lock_path,
                supervisor_contender_metadata,
            )
        )
        (
            supervisor_contender_acquired,
            supervisor_contender_reason,
            supervisor_contender_owner,
        ) = supervisor_contender_observations[-1]
        assert supervisor_contender_acquired is False
        assert supervisor_contender_reason == "lock_exists"
        assert supervisor_contender_owner == published_lock
        materializations.append(kwargs)
        if advance_target_during_first_materialization["pending"]:
            advance_target_during_first_materialization["pending"] = False
            (case.repo / "concurrent-target-advance.txt").write_text(
                "simulated checkout mutation that ignored the lock\n",
                encoding="utf-8",
            )
            _git(case.repo, "add", "concurrent-target-advance.txt")
            _git(case.repo, "commit", "-m", "simulate target advance")
        return dict(seed)

    monkeypatch.setattr(
        case.daemon,
        "_materialize_post_merge_recovery_seed",
        materialize,
    )
    seed_validations = []

    def validate_seed(*, expected_target_commit="", **kwargs):
        seed_validations.append(kwargs)
        live_target_commit = _git(
            case.repo,
            "rev-parse",
            case.daemon._main_branch_name(),
        )
        if expected_target_commit != live_target_commit:
            return {}, "recovery_seed_target_changed"
        assert {
            name: kwargs[name] for name in seed
        } == seed
        if replace_lock_during_validation["pending"]:
            replace_lock_during_validation["pending"] = False
            merge_lock_path = case.daemon._repo_merge_lock_path()
            published_lock = json.loads(
                merge_lock_path.read_text(encoding="utf-8")
            )
            replacement_lock_metadata.update(
                {
                    **published_lock,
                    "lease_id": "replacement-checkout-contender",
                    "operation": "replacement_checkout_contender",
                }
            )
            assert case.daemon._release_published_merge_lock(
                merge_lock_path,
                published_lock,
            )
            acquired, reason, existing = (
                case.daemon._try_acquire_published_merge_lock(
                    merge_lock_path,
                    replacement_lock_metadata,
                )
            )
            assert acquired is True
            assert reason == "acquired"
            assert existing is None
        return {
            **seed,
            "recovery_seed_parent_commit": live_target_commit,
        }, ""

    monkeypatch.setattr(
        case.daemon,
        "_validated_post_merge_recovery_seed_commit",
        validate_seed,
    )
    migration_kwargs = {
        "task": case.task,
        "denial_id": denials[0]["denial_id"],
        "legacy_denial_consumption_id": consumptions[0][
            "consumption_id"
        ],
        "attempt_events": attempt_events,
        "recovery_seed_submodule_path": seed[
            "recovery_seed_submodule_path"
        ],
        "recovery_seed_submodule_commit": seed[
            "recovery_seed_submodule_commit"
        ],
    }

    historical_board = case.daemon.todo_path.read_bytes()
    current_board = historical_board + (
        b"\n## REV-999 Document an unrelated follow-up\n\n"
        b"- Status: todo\n"
        b"- Completion: manual\n"
        b"- Priority: P2\n"
        b"- Track: docs\n"
        b"- Outputs: docs/unrelated.md\n"
        b"- Validation: test -f docs/unrelated.md\n"
        b"- Acceptance: The unrelated document exists.\n"
        b"- Board namespace: uiir-test\n"
    )
    case.daemon.todo_path.write_bytes(current_board)
    _git(case.repo, "add", "tasks.todo.md")
    _git(case.repo, "commit", "-m", "add unrelated later task")
    strict_ledger = list(
        post_merge_review_module._strict_event_ledger(
            case.daemon.events_path
        )
    )
    missing_binding_event_ids = {
        str(event["event_id"])
        for event in strict_ledger
        if event.get("type")
        in {"implementation_started", "implementation_finished"}
        and not event.get("task_binding_id")
        and event.get("attempt") in {2, 3, 4}
    }
    assert case.daemon._verified_legacy_high_water_task_bindings(
        task=case.task,
        events=strict_ledger,
        expected_target_commit=_git(case.repo, "rev-parse", "HEAD"),
        required_event_ids={
            str(entry[field])
            for entry in attempt_events
            for field in ("started_event_id", "terminal_event_id")
        },
    ) == {
        event_id: task_binding_id
        for event_id in missing_binding_event_ids
    }

    mutated_board = current_board.replace(
        b"## REV-001 Review a nested implementation",
        b"## REV-001 Review a mutated nested implementation",
        1,
    )
    assert mutated_board != current_board
    case.daemon.todo_path.write_bytes(
        mutated_board
    )
    try:
        with pytest.raises(
            MergeQueueFenceError,
            match="task revision changed",
        ):
            case.daemon.migrate_legacy_post_merge_correction_high_water(
                **migration_kwargs
            )
    finally:
        case.daemon.todo_path.write_bytes(current_board)
    assert materializations == []

    recovery_event_id = attempt_events[-1]["terminal_event_id"]

    def rejected_with_ledger(
        ledger,
        *,
        events=attempt_events,
        error=MergeQueueIntegrityError,
        match,
    ):
        with monkeypatch.context() as scoped:
            scoped.setattr(
                post_merge_review_module,
                "_strict_event_ledger",
                lambda _path: tuple(ledger),
            )
            with pytest.raises(error, match=match):
                case.daemon.migrate_legacy_post_merge_correction_high_water(
                    **{
                        **migration_kwargs,
                        "attempt_events": events,
                    }
                )

    for recovery_mutation in (
        "reason",
        "payload",
        "attempt_type",
        "consumed",
        "previous_count",
        "top_level_consumption",
    ):
        malformed_recovery_ledger = deepcopy(strict_ledger)
        malformed_recovery = next(
            event
            for event in malformed_recovery_ledger
            if event.get("event_id") == recovery_event_id
        )
        if recovery_mutation == "reason":
            malformed_recovery["reason"] = "operator_reset"
        elif recovery_mutation == "payload":
            malformed_recovery["attempt_recovery"]["attempt"] = 99
        elif recovery_mutation == "attempt_type":
            malformed_recovery["attempt_recovery"]["attempt"] = 4.0
        elif recovery_mutation == "consumed":
            malformed_recovery["attempt_recovery"]["consumed"] = True
        elif recovery_mutation == "previous_count":
            malformed_recovery["attempt_recovery"][
                "previous_display_count"
            ] = 5
        else:
            malformed_recovery["attempt_consumed"] = True
        rejected_with_ledger(
            malformed_recovery_ledger,
            match="recovery terminal is invalid",
        )
    assert materializations == []

    malformed_outer_attempt_ledger = deepcopy(strict_ledger)
    next(
        event
        for event in malformed_outer_attempt_ledger
        if event.get("event_id") == recovery_event_id
    )["attempt"] = 4.0
    rejected_with_ledger(
        malformed_outer_attempt_ledger,
        match="ledger binding changed",
    )

    mismatched_branch_ledger = deepcopy(strict_ledger)
    next(
        event
        for event in mismatched_branch_ledger
        if event.get("event_id") == recovery_event_id
    )["branch"] = "implementation/different-attempt-4"
    rejected_with_ledger(
        mismatched_branch_ledger,
        match="lifecycle binding is incoherent",
    )

    mismatched_baseline_ledger = deepcopy(strict_ledger)
    attempt_three_terminal_id = attempt_events[1]["terminal_event_id"]
    next(
        event
        for event in mismatched_baseline_ledger
        if event.get("event_id") == attempt_three_terminal_id
    )["baseline_ref"] = "f" * 40
    rejected_with_ledger(
        mismatched_baseline_ledger,
        match="terminal did not consume a failure",
    )
    assert materializations == []

    terminal_above_high_water = deepcopy(
        next(
            event
            for event in strict_ledger
            if event.get("event_id") == recovery_event_id
        )
    )
    terminal_above_high_water.update(
        {
            "event_id": "sha256:" + ("a" * 64),
            "sequence": max(
                int(event.get("sequence") or 0)
                for event in strict_ledger
            )
            + 1,
            "attempt": 5,
        }
    )
    terminal_above_high_water["attempt_recovery"]["attempt"] = 5
    rejected_with_ledger(
        [*strict_ledger, terminal_above_high_water],
        error=MergeQueueFenceError,
        match="terminal above the high-water",
    )

    unverified_queue_terminal = deepcopy(
        next(
            event
            for event in strict_ledger
            if event.get("event_id") == recovery_event_id
        )
    )
    unverified_queue_terminal.update(
        {
            "type": (
                post_merge_review_module
                .POST_MERGE_CORRECTION_QUEUE_RECONCILED_EVENT
            ),
            "event_id": "sha256:" + ("b" * 64),
            "sequence": unverified_queue_terminal["sequence"] + 1,
            "attempt_consumed": True,
        }
    )
    unverified_queue_events = deepcopy(attempt_events)
    unverified_queue_events[-1].update(
        {
            "terminal_event_id": unverified_queue_terminal["event_id"],
            "terminal_event_sequence": unverified_queue_terminal[
                "sequence"
            ],
            "terminal_event_type": unverified_queue_terminal["type"],
        }
    )
    rejected_with_ledger(
        [*strict_ledger, unverified_queue_terminal],
        events=unverified_queue_events,
        match="queue terminal is not verified",
    )
    assert materializations == []

    with pytest.raises(
        MergeQueueFenceError,
        match="recovery seed lost its target fence",
    ):
        case.daemon.migrate_legacy_post_merge_correction_high_water(
            **migration_kwargs
        )
    assert case.queue.verified_post_merge_correction_chain() == ()
    assert not case.daemon._repo_merge_lock_path().exists()

    replace_lock_during_validation["pending"] = True
    with pytest.raises(
        MergeQueueFenceError,
        match="checkout mutation lease was lost before commit",
    ):
        case.daemon.migrate_legacy_post_merge_correction_high_water(
            **migration_kwargs
        )
    assert case.queue.verified_post_merge_correction_chain() == ()
    assert json.loads(
        case.daemon._repo_merge_lock_path().read_text(encoding="utf-8")
    ) == replacement_lock_metadata
    assert case.daemon._release_published_merge_lock(
        case.daemon._repo_merge_lock_path(),
        replacement_lock_metadata,
    )
    assert not case.daemon._repo_merge_lock_path().exists()

    record_anchor = (
        case.queue.record_post_merge_correction_legacy_high_water_anchor
    )

    def record_anchor_under_lock(*args, **kwargs):
        assert case.daemon._repo_merge_lock_path().exists()
        return record_anchor(*args, **kwargs)

    monkeypatch.setattr(
        case.queue,
        "record_post_merge_correction_legacy_high_water_anchor",
        record_anchor_under_lock,
    )

    anchor = (
        case.daemon.migrate_legacy_post_merge_correction_high_water(
            **migration_kwargs
        )
    )
    validations_after_anchor = len(seed_validations)
    repeated = (
        case.daemon.migrate_legacy_post_merge_correction_high_water(
            **migration_kwargs
        )
    )

    assert repeated == anchor
    assert len(materializations) == 3
    assert len(contender_observations) == 3
    assert len(supervisor_contender_observations) == 3
    assert len(set(published_lease_ids)) == 3
    assert len(seed_validations) == validations_after_anchor + 1
    assert anchor["record_kind"] == "legacy_high_water_anchored"
    assert anchor["attempt"] == 4
    assert anchor["detail"]["legacy_denial_consumption_id"] == (
        consumptions[0]["consumption_id"]
    )
    assert anchor["detail"]["attempt_events"] == attempt_events
    assert {
        name: anchor["detail"][name] for name in seed
    } == seed
    authority = case.queue.verified_post_merge_correction_authority(
        denials[0]["denial_id"]
    )
    assert authority["state"] == "legacy_high_water_anchored"
    assert authority["authorized_attempt"] == 4
    assert authority["authority_available"] is False
    persisted_state = TodoTaskState.load(case.daemon.state_path)
    assert persisted_state.implementation_attempts[case.task.task_id] == 4
    assert (
        persisted_state.implementation_attempts_by_cid[
            case.identity.canonical_task_cid
        ]
        == 4
    )

    for seed_failure_reason in (
        "recovery_seed_commit_unavailable",
        "recovery_seed_tree_mismatch",
        "recovery_seed_parent_mismatch",
        "recovery_seed_retention_ref_missing",
        "recovery_seed_child_retention_ref_missing",
    ):
        monkeypatch.setattr(
            case.daemon,
            "_validated_post_merge_recovery_seed_commit",
            lambda _reason=seed_failure_reason, **_kwargs: ({}, _reason),
        )
        with pytest.raises(
            MergeQueueIntegrityError,
            match=seed_failure_reason,
        ):
            case.daemon.migrate_legacy_post_merge_correction_high_water(
                **migration_kwargs
            )
    assert len(materializations) == 3
    monkeypatch.setattr(
        case.daemon,
        "_validated_post_merge_recovery_seed_commit",
        validate_seed,
    )

    tampered_events = deepcopy(attempt_events)
    tampered_events[-1]["terminal_event_id"] = "sha256:" + ("d" * 64)
    with pytest.raises(
        (MergeQueueFenceError, MergeQueueIntegrityError),
    ):
        case.daemon.migrate_legacy_post_merge_correction_high_water(
            **{
                **migration_kwargs,
                "attempt_events": tampered_events,
            }
        )


def test_exact_recovery_seed_enqueue_preserves_child_integration_target(
    tmp_path,
    monkeypatch,
):
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    _git(repo, "checkout", "-b", "main")
    _git(repo, "config", "user.name", "Test User")
    _git(repo, "config", "user.email", "test@example.invalid")
    (repo / "todo.md").write_text("# Todos\n", encoding="utf-8")
    _git(repo, "add", "todo.md")
    _git(repo, "commit", "-m", "baseline")
    state_dir = repo / "state"
    daemon = TodoImplementationDaemon(
        todo_path=repo / "todo.md",
        state_path=state_dir / "task_state.json",
        strategy_path=state_dir / "strategy.json",
        events_path=state_dir / "events.jsonl",
        repo_root=repo,
        merge_target_branch="main",
    )
    task = PortalTask(
        task_id="UIR-002",
        title="Recover a reviewed UIIR child commit",
        status="todo",
        completion="manual",
        priority="P0",
        track="logic",
        outputs=["external/ipfs_datasets_py/UI_UX_IR.py"],
    )
    state = TodoTaskState()
    recovery_path = "external/ipfs_datasets_py"
    baseline = "1" * 40
    implementation_commit = "2" * 40
    baseline_child = "3" * 40
    preflight_child = "4" * 40
    recovery_child = "5" * 40
    captured: list[dict[str, object]] = []

    monkeypatch.setattr(
        daemon,
        "_reject_protected_merge_candidate",
        lambda **_kwargs: {},
    )
    monkeypatch.setattr(
        daemon,
        "_release_pooled_worktree_lease",
        lambda *_args, **_kwargs: {"attempted": False, "released": False},
    )
    monkeypatch.setattr(
        daemon,
        "_root_tree_gitlink_ref",
        lambda _repo, ref, _path: (
            (recovery_child, "")
            if ref == implementation_commit
            else (baseline_child, "")
        ),
    )
    monkeypatch.setattr(
        daemon,
        "_git_ref_ancestor_check_in_repo",
        lambda _repo, ancestor, descendant: (
            ancestor == preflight_child and descendant == recovery_child
        ),
    )
    monkeypatch.setattr(
        daemon,
        "_root_submodule_changed_in_task",
        lambda candidate, base, path: (
            candidate == implementation_commit
            and base == baseline
            and path == recovery_path
        ),
    )

    def fake_enqueue(**kwargs):
        captured.append(kwargs)
        return SimpleNamespace(request_id="request-1"), {
            "queued": True,
            "merged": False,
            "reason": "queued",
        }

    monkeypatch.setattr(daemon, "_enqueue_merge_candidate", fake_enqueue)
    merge_consumptions = []

    def consume_before_strict_terminal():
        merge_consumptions.append(True)
        pytest.fail(
            "recovery candidate consumed before its strict terminal"
        )

    monkeypatch.setattr(
        daemon,
        "_consume_one_merge_candidate",
        consume_before_strict_terminal,
    )

    result = daemon._enqueue_validated_worktree(
        state=state,
        task=task,
        attempt=5,
        branch_name="implementation/uir-002-attempt-5",
        baseline_ref=baseline,
        worktree_path=repo / "worktree",
        implementation_commit=implementation_commit,
        commit_result={
            "submodule_results": [],
            "recovery_seed_zero_edit_promotion_guard": {
                "applicable": True,
                "allowed": True,
                "durable_consumption_verified": True,
                "reasons": [],
                "recovery_seed_ref": implementation_commit,
                "recovery_seed_submodule_path": recovery_path,
                "recovery_seed_submodule_commit": recovery_child,
            },
        },
        validation_result={"attempted": True, "passed": True},
        approved_submodule_integration_targets={
            recovery_path: {
                "gitlink_baseline": baseline_child,
                "integration_target": preflight_child,
                "relation": "integration_target_ancestor",
            },
        },
    )

    assert result["queued"] is True
    assert result["producer_terminal_pending"] is True
    assert "train_result" not in result
    assert captured[0]["changed_submodule_paths"] == [recovery_path]
    approved = captured[0]["approved_submodule_integration_targets"]
    assert approved[recovery_path]["integration_target"] == preflight_child
    assert approved[recovery_path]["relation"] == "integration_target_ancestor"
    assert merge_consumptions == []


def test_validation_prunes_unchanged_start_context_after_daemon_restart(tmp_path):
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    _git(repo, "checkout", "-b", "main")
    _git(repo, "config", "user.name", "Agent Test")
    _git(repo, "config", "user.email", "agent@example.test")
    (repo / "README.md").write_text("baseline\n", encoding="utf-8")
    _git(repo, "add", "README.md")
    _git(repo, "commit", "-m", "baseline")

    initial = repo / "docs" / "architecture" / "initial-context.md"
    initial.parent.mkdir(parents=True)
    initial.write_text("available at task start\n", encoding="utf-8")
    changed = repo / "docs" / "architecture" / "changed-context.md"
    changed.write_text("available at task start\n", encoding="utf-8")
    worktree_root = tmp_path / "worktrees"
    state_path = tmp_path / "state" / "task_state.json"
    strategy_path = tmp_path / "state" / "strategy.json"
    events_path = tmp_path / "state" / "events.jsonl"
    daemon = TodoImplementationDaemon(
        todo_path=tmp_path / "todo.md",
        state_path=state_path,
        strategy_path=strategy_path,
        events_path=events_path,
        repo_root=repo,
        use_ephemeral_worktree=True,
        worktree_root=worktree_root,
        worktree_pool_enabled=False,
        merge_target_branch="main",
    )
    worktree = worktree_root / "attempt"
    branch = "implementation/context-snapshot"

    daemon._create_seeded_worktree(worktree, branch)
    assert (worktree / initial.relative_to(repo)).read_text(encoding="utf-8") == (
        "available at task start\n"
    )
    changed_in_worktree = worktree / changed.relative_to(repo)
    changed_in_worktree.write_text("changed by implementation\n", encoding="utf-8")

    late = repo / "docs" / "architecture" / "late-concurrent-context.md"
    late.write_text("created by another lane\n", encoding="utf-8")
    restarted_daemon = TodoImplementationDaemon(
        todo_path=tmp_path / "todo.md",
        state_path=state_path,
        strategy_path=strategy_path,
        events_path=events_path,
        repo_root=repo,
        use_ephemeral_worktree=True,
        worktree_root=worktree_root,
        worktree_pool_enabled=False,
        merge_target_branch="main",
    )
    restarted_daemon._prepare_worktree_for_validation(worktree, branch_name=branch)

    assert not (worktree / late.relative_to(repo)).exists()
    assert not (worktree / initial.relative_to(repo)).exists()
    assert changed_in_worktree.read_text(encoding="utf-8") == "changed by implementation\n"
    status = _git(worktree, "status", "--short", "--untracked-files=all")
    assert status.splitlines() == ["?? docs/architecture/changed-context.md"]
    assert not restarted_daemon.worktree_context_snapshot_path.exists()
    cleanup = restarted_daemon._cleanup_merged_worktree(worktree, branch)
    assert cleanup["cleaned"] is True


def test_implementation_daemon_shares_repository_gc_state_across_lanes(tmp_path):
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    _git(repo, "checkout", "-b", "main")
    _git(repo, "config", "user.name", "Test User")
    _git(repo, "config", "user.email", "test@example.invalid")
    todo_path = repo / "todo.md"
    todo_path.write_text("# Todos\n", encoding="utf-8")
    _git(repo, "add", "todo.md")
    _git(repo, "commit", "-m", "seed todo")
    linked = tmp_path / "linked"
    _git(repo, "worktree", "add", "-b", "lane", str(linked))

    first = TodoImplementationDaemon(
        todo_path=todo_path,
        state_path=tmp_path / "lanes" / "first" / "task_state.json",
        strategy_path=tmp_path / "lanes" / "first" / "strategy.json",
        events_path=tmp_path / "lanes" / "first" / "events.jsonl",
        repo_root=repo,
    )
    first.git_gc.state.last_gc_time = 123.0
    first.git_gc.state.save()

    second = TodoImplementationDaemon(
        todo_path=linked / "todo.md",
        state_path=tmp_path / "lanes" / "second" / "task_state.json",
        strategy_path=tmp_path / "lanes" / "second" / "strategy.json",
        events_path=tmp_path / "lanes" / "second" / "events.jsonl",
        repo_root=linked,
    )

    expected = repo / ".git" / "agent-supervisor" / "gc_state.json"
    assert first.git_gc.state_path == expected
    assert second.git_gc.state_path == expected
    assert second.git_gc.state.last_gc_time == 123.0
    assert first.git_gc.state_path != repo / "data" / "agent_supervisor" / "gc_state.json"
    assert second.git_gc.state_path != linked / "data" / "agent_supervisor" / "gc_state.json"
    assert first.git_gc.needs_aggressive_gc() is False
    assert second.git_gc.needs_aggressive_gc() is False
    assert _git(repo, "status", "--porcelain") == ""
    assert _git(linked, "status", "--porcelain") == ""


