def test_non_consuming_target_event_preserves_exact_correction_attempt(
    post_merge_denial_case_factory,
    monkeypatch,
):
    case = post_merge_denial_case_factory()
    original = case.daemon._post_merge_review_correction_for_task(
        case.task
    )
    assert original is not None
    assert original["target_implementation_attempt"] == 2
    _complete_post_merge_denial_queue(case)
    case.daemon._record_event(
        "implementation_finished",
        {
            "task_id": case.task.task_id,
            "canonical_task_key": case.identity.canonical_task_key,
            "canonical_task_cid": case.identity.canonical_task_cid,
            "board_namespace": case.identity.board_namespace,
            "attempt": 2,
            "attempt_consumed": False,
            "provider_call_allowed": False,
            "branch": "implementation/rev-001-attempt-2-deferred",
            "implementation_commit": "",
            "returncode": 1,
            "merge_result": {
                "attempted": False,
                "merged": False,
                "reason": "provider_capacity_backoff",
            },
            "cleanup_result": {
                "cleaned": True,
                "reason": "deferred_attempt_cleaned",
            },
        },
    )
    retained = case.daemon._post_merge_review_correction_for_task(
        case.task
    )
    assert retained is not None
    assert retained["source_event_id"] == original["source_event_id"]
    feedback = case.daemon._post_merge_review_feedback_for_attempt(
        case.task,
        2,
    )
    assert feedback
    TodoTaskState(
        implementation_attempts={case.task.task_id: 1},
        implementation_attempts_by_cid={
            case.identity.canonical_task_cid: 1,
        },
        task_identities={
            case.task.task_id: case.identity.to_dict(),
        },
    ).save(case.daemon.state_path)
    implementation_calls: list[tuple[str, int, bool]] = []
    monkeypatch.setattr(
        case.daemon,
        "_consume_one_merge_candidate",
        lambda: None,
    )

    def implement(
        selected,
        state,
        *,
        post_merge_correction_authority=None,
    ):
        assert (
            post_merge_correction_authority or {}
        ).get("authority_kind") == "review_denial"
        attempt = case.daemon._task_attempt(state, selected)
        prompt = case.daemon._build_implementation_prompt(
            selected,
            attempt,
        )
        prompt_payload, correction_evidence = (
            _post_merge_correction_prompt_evidence(prompt)
        )
        finding = original["findings"][0]
        implementation_calls.append(
            (
                selected.task_id,
                attempt,
                all(
                    binding in correction_evidence
                    for binding in (
                        finding["finding_id"],
                        finding["code"],
                        original["task_binding_id"],
                        original["source_event_id"],
                    )
                )
                and (
                    prompt_payload["goal"][
                        "post_merge_review_correction_binding"
                    ]["feedback_id"]
                    == json.loads(feedback)["feedback_id"]
                ),
            )
        )
        return {"returncode": 0}

    monkeypatch.setattr(case.daemon, "_run_implementation", implement)
    case.daemon.implement = True

    result = case.daemon.run_once()
    state = TodoTaskState.load(case.daemon.state_path)

    assert result["shared_completed_task_ids"] == []
    assert result["post_merge_denied_completion_task_ids"] == [
        case.task.task_id
    ]
    assert result["active_task_id"] == case.task.task_id
    assert implementation_calls == [(case.task.task_id, 2, True)]
    assert state.implementation_attempts[case.task.task_id] == 1
    assert state.implementation_attempts_by_cid[
        case.identity.canonical_task_cid
    ] == 1
    assert state.task_statuses[case.task.task_id] == "ready"


def test_older_post_merge_denial_does_not_reopen_newer_candidate(
    post_merge_denial_case_factory,
):
    case = post_merge_denial_case_factory()
    (case.repo / "verified.txt").write_text(
        "second implementation\n",
        encoding="utf-8",
    )
    _git(case.repo, "add", "verified.txt")
    _git(case.repo, "commit", "-m", "RETRY-001: correction candidate")
    newer_commit = _git(case.repo, "rev-parse", "HEAD")
    newer_tree = "git-tree:" + _git(
        case.repo,
        "rev-parse",
        f"{newer_commit}^{{tree}}",
    )
    newer_branch = "implementation/retry-001-attempt-2"
    case.daemon._record_event(
        "implementation_finished",
        {
            "task_id": case.task.task_id,
            "attempt": 2,
            "branch": newer_branch,
            "implementation_commit": newer_commit,
            "returncode": 0,
            "merge_result": {
                "attempted": True,
                "merged": True,
                "merge_commit": newer_commit,
            },
            "cleanup_result": {"cleaned": True},
        },
    )
    newer_pending = case.daemon._record_event(
        "merge_acceptance_pending",
        {
            "task_id": case.task.task_id,
            "task_binding_id": (
                post_merge_review_module.post_merge_task_binding_id(
                    case.task
                )
            ),
            "canonical_task_key": case.identity.canonical_task_key,
            "canonical_task_cid": case.identity.canonical_task_cid,
            "board_namespace": case.identity.board_namespace,
            "attempt": 2,
            "queue_attempt": 2,
            "implementation_attempt": 2,
            "branch": newer_branch,
            "baseline_ref": case.merge_commit,
            "implementation_commit": newer_commit,
            "merge_commit": newer_commit,
            "repository_tree_id": newer_tree,
            "merge_integrated": True,
            "authoritatively_completed": False,
            "resolved": False,
            "reason": "authoritative_acceptance_pending",
        },
    )

    assert (
        case.daemon._post_merge_review_correction_for_task(
            case.task.task_id
        )
        is None
    )
    assert case.daemon._post_merge_review_corrections_by_task() == {}
    assert case.daemon._post_merge_review_feedback_for_attempt(
        case.task,
        2,
    ) == ""
    assert case.daemon._failed_merge_candidates() == [newer_pending]


def test_post_merge_denial_feedback_is_bounded_and_exactly_attempt_scoped(
    post_merge_denial_case_factory,
):
    findings = [
        {
            "code": f"correction-{index}",
            "severity": "high" if index == 0 else "medium",
            "summary": f"Finding {index}: " + ("x" * 1_800),
        }
        for index in range(8)
    ]
    case = post_merge_denial_case_factory(findings=findings)

    feedback = case.daemon._post_merge_review_feedback_for_attempt(
        case.task,
        2,
    )

    assert isinstance(feedback, str)
    assert 0 < len(feedback.encode("utf-8")) <= 8_192
    assert "correction-0" in feedback
    assert "high" in feedback
    assert "Finding 0:" in feedback
    assert "review_response_text" not in feedback
    assert "implementer_provenance" not in feedback
    assert str(case.outcome.receipt["receipt_id"]) not in feedback
    assert case.daemon._post_merge_review_feedback_for_attempt(
        case.task,
        1,
    ) == ""
    assert case.daemon._post_merge_review_feedback_for_attempt(
        case.task,
        3,
    ) == ""

    prior_attempt = case.daemon._build_implementation_prompt(
        case.task,
        attempt=1,
    )
    correction_attempt = case.daemon._build_implementation_prompt(
        case.task,
        attempt=2,
    )

    assert "correction-0" not in prior_attempt
    prior_rules = json.loads(prior_attempt)["authority"][
        "generic_prompt_policy"
    ]
    assert all(
        "Preserve every existing test function symbol" not in rule
        for rule in prior_rules
    )
    feedback_payload = json.loads(feedback)
    correction_payload, correction_evidence = (
        _post_merge_correction_prompt_evidence(correction_attempt)
    )
    first_finding = feedback_payload["findings"][0]
    assert correction_payload["goal"][
        "post_merge_review_correction_binding"
    ]["feedback_id"] == feedback_payload["feedback_id"]
    assert first_finding["finding_id"] in correction_evidence
    assert first_finding["code"] in correction_evidence
    assert feedback_payload["task_binding_id"] in correction_evidence
    assert feedback_payload["source_event_id"] in correction_evidence
    correction_rules = correction_payload["authority"][
        "generic_prompt_policy"
    ]
    assert any(
        "Preserve every existing test function symbol" in rule
        and "Free-text review findings do not authorize" in rule
        for rule in correction_rules
    )


def test_post_merge_correction_bypasses_stale_retry_context_and_addendum(
    post_merge_denial_case_factory,
):
    case = post_merge_denial_case_factory()
    base = case.daemon._compile_implementation_context(
        case.task,
        attempt=1,
    )
    stale_addendum = "STALE-RETRY-ADDENDUM-MUST-NOT-BE-DISPATCHED"
    diagnostic = case.daemon.record_implementation_failure_context(
        case.task,
        {
            "kind": "validation_failure",
            "reason": "pre-review failure",
            "next_attempt_prompt_addendum": stale_addendum,
        },
    )
    key = case.daemon._canonical_ref(case.task)
    parent = case.daemon._implementation_parent(case.task)
    assert parent == (base.capsule, base.receipt.receipt_id)
    assert diagnostic.prior_decision_id == base.receipt.receipt_id
    assert case.daemon._implementation_diagnostics[key] == diagnostic

    prompt = case.daemon._build_implementation_prompt(
        case.task,
        attempt=2,
    )
    prompt_payload, correction_evidence = (
        _post_merge_correction_prompt_evidence(prompt)
    )
    correction = case.daemon._post_merge_review_correction_for_task(
        case.task
    )

    assert correction is not None
    assert prompt_payload["goal"]["attempt"] == 2
    assert prompt_payload["goal"][
        "post_merge_review_correction_binding"
    ]["source_event_id"] == correction["source_event_id"]
    assert correction["findings"][0]["finding_id"] in correction_evidence
    assert stale_addendum not in prompt
    assert "Prior failure review" not in prompt
    assert case.daemon._last_implementation_retry is None
    assert isinstance(
        case.daemon._last_implementation_context,
        ContextCompileResult,
    )


def test_removed_baseline_test_symbols_survive_retry_projection() -> None:
    secret_symbol = (
        "test_sk_live_51H8xYzAbCdEfGhIjKlMnOpQrStUvWxY"
    )
    unrelated_secret_symbol = (
        "test_ghp_41H8xYzAbCdEfGhIjKlMnOpQrStUvWxY"
    )
    finding = SimpleNamespace(
        code=SimpleNamespace(value="test_weakening_forbidden"),
        path="tests/test_identity.py",
        message="test assertions or execution were weakened",
    )
    proposal_validation = SimpleNamespace(
        accepted=False,
        findings=(finding,),
        proposal=SimpleNamespace(
            proposal_id="proposal:identity",
            repository_tree_id="a" * 40,
            changed_paths=("tests/test_identity.py",),
            candidate_diff=(
                SimpleNamespace(
                    path="tests/test_identity.py",
                    before_source=(
                        "def test_stable_identity() -> None:\n"
                        "    assert stable_identity()\n"
                        f"def {secret_symbol}() -> None:\n"
                        "    assert False\n"
                    ),
                    after_source=(
                        "def test_new_identity() -> None:\n"
                        "    assert new_identity()\n"
                    ),
                ),
                SimpleNamespace(
                    path="src/unrelated.py",
                    before_source=(
                        f"def {unrelated_secret_symbol}() -> None:\n"
                        "    assert False\n"
                    ),
                    after_source=(
                        "def test_unrelated_replacement() -> None:\n"
                        "    assert True\n"
                    ),
                ),
            ),
        ),
        policy=SimpleNamespace(policy_id="policy:identity"),
        receipt=SimpleNamespace(receipt_id="receipt:identity"),
    )

    compact = TodoImplementationDaemon._compact_proposal_validation(
        proposal_validation
    )
    normalized = TodoImplementationDaemon._normalize_implementation_failure(
        {"validation_result": {"proposal_gate": compact}}
    )

    assert compact["removed_baseline_test_symbols"] == [
        {
            "path": "tests/test_identity.py",
            "missing_baseline_test_symbols": ["test_stable_identity"],
            "missing_baseline_test_symbol_count": 2,
            "missing_baseline_test_symbols_truncated": True,
        }
    ]
    assert compact["removed_baseline_test_path_count"] == 1
    assert compact["removed_baseline_test_paths_truncated"] is False
    assert normalized["proposal_gate"][
        "removed_baseline_test_symbols"
    ] == (
        compact["removed_baseline_test_symbols"]
    )
    serialized = json.dumps(
        normalized,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    assert secret_symbol not in serialized
    assert unrelated_secret_symbol not in serialized


def test_removed_baseline_test_symbol_projection_is_exact_and_bounded() -> None:
    ordinary_symbols = [
        f"test_removed_{index:02d}" for index in range(17)
    ]
    oversized_symbol = "test_" + ("x" * 300)
    control_paths = tuple(
        "tests/" + ("\x01" * 480) + f"-{index}.py"
        for index in range(8)
    )
    control_path_entries = tuple(
        SimpleNamespace(
            path=path,
            before_source=(
                f"def test_control_path_{index}() -> None:\n"
                "    assert True\n"
            ),
            after_source=(
                "def test_replacement() -> None:\n"
                "    assert True\n"
            ),
        )
        for index, path in enumerate(control_paths)
    )
    before_source = "".join(
        f"def {symbol}() -> None:\n    assert True\n"
        for symbol in (*ordinary_symbols, oversized_symbol)
    )
    unrelated_findings = tuple(
        SimpleNamespace(
            code=SimpleNamespace(value=f"unrelated_{index}"),
            path=f"unrelated-{index}.txt",
            message="unrelated finding",
        )
        for index in range(8)
    )
    weakening_paths = (
        "tests/test_identity.py",
        "tests/\udcff-invalid.py",
        *control_paths,
    )
    findings = unrelated_findings + tuple(
        SimpleNamespace(
            code=SimpleNamespace(value="test_weakening_forbidden"),
            path=path,
            message="test assertions or execution were weakened",
        )
        for path in weakening_paths
    )
    proposal_validation = SimpleNamespace(
        accepted=False,
        findings=findings,
        proposal=SimpleNamespace(
            proposal_id="proposal:bounded-identity",
            repository_tree_id="a" * 40,
            changed_paths=("tests/test_identity.py",),
            candidate_diff=(
                SimpleNamespace(
                    path="tests/test_identity.py",
                    before_source=before_source,
                    after_source=(
                        "def test_replacement() -> None:\n"
                        "    assert True\n"
                    ),
                ),
                SimpleNamespace(
                    path="tests/\udcff-invalid.py",
                    before_source=(
                        "def test_invalid_path_identity() -> None:\n"
                        "    assert True\n"
                    ),
                    after_source=(
                        "def test_replacement() -> None:\n"
                        "    assert True\n"
                    ),
                ),
                *control_path_entries,
            ),
        ),
        policy=SimpleNamespace(policy_id="policy:identity"),
        receipt=SimpleNamespace(receipt_id="receipt:identity"),
    )

    compact = TodoImplementationDaemon._compact_proposal_validation(
        proposal_validation
    )
    normalized = TodoImplementationDaemon._normalize_implementation_failure(
        {"validation_result": {"proposal_gate": compact}}
    )
    record = compact["removed_baseline_test_symbols"][0]

    assert record["missing_baseline_test_symbols"] == ordinary_symbols[:16]
    assert record["missing_baseline_test_symbol_count"] == 18
    assert record["missing_baseline_test_symbols_truncated"] is True
    assert compact["removed_baseline_test_path_count"] == 10
    assert compact["removed_baseline_test_paths_truncated"] is True
    assert all(
        symbol != oversized_symbol
        and not oversized_symbol.startswith(symbol)
        for symbol in record["missing_baseline_test_symbols"]
    )
    assert len(
        json.dumps(
            normalized,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ) < 16_384


def test_removed_baseline_test_symbol_reaches_retry_provider_prompt(
    tmp_path: Path,
) -> None:
    secret_symbol = (
        "test_ghp_31H8xYzAbCdEfGhIjKlMnOpQrStUvWxY"
    )
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    _git(repo, "checkout", "-b", "main")
    _git(repo, "config", "user.name", "Test User")
    _git(repo, "config", "user.email", "test@example.invalid")
    test_path = repo / "tests" / "test_identity.py"
    test_path.parent.mkdir(parents=True)
    test_path.write_text(
        "def test_stable_identity() -> None:\n"
        "    assert stable_identity()\n",
        encoding="utf-8",
    )
    _git(repo, "add", "tests/test_identity.py")
    _git(repo, "commit", "-m", "baseline identity test")
    daemon = TodoImplementationDaemon(
        todo_path=repo / "todo.md",
        state_path=repo / "state" / "task_state.json",
        strategy_path=repo / "state" / "strategy.json",
        events_path=repo / "state" / "events.jsonl",
        repo_root=repo,
        worktree_submodule_paths=[],
    )
    task = PortalTask(
        task_id="UIR-002",
        title="Freeze identity semantics",
        status="todo",
        completion="manual",
        priority="P0",
        track="identity",
        outputs=["tests/test_identity.py"],
        validation=["python -m pytest tests/test_identity.py -q"],
        metadata={
            "ast symbols": ",".join(
                f"aaa_metadata_symbol_{index:03d}"
                for index in range(300)
            )
        },
    )
    daemon._compile_implementation_context(task, attempt=1)
    daemon._persist_implementation_context_receipt_unchecked(
        task,
        attempt=1,
    )
    proposal_validation = SimpleNamespace(
        accepted=False,
        findings=(
            SimpleNamespace(
                code=SimpleNamespace(value="test_weakening_forbidden"),
                path="tests/test_identity.py",
                message="test assertions or execution were weakened",
            ),
        ),
        proposal=SimpleNamespace(
            proposal_id="proposal:identity",
            repository_tree_id=_git(repo, "rev-parse", "HEAD"),
            changed_paths=("tests/test_identity.py",),
            candidate_diff=(
                SimpleNamespace(
                    path="tests/test_identity.py",
                    before_source=(
                        "def test_stable_identity() -> None:\n"
                        "    assert stable_identity()\n"
                        f"def {secret_symbol}() -> None:\n"
                        "    assert False\n"
                    ),
                    after_source=(
                        "def test_new_identity() -> None:\n"
                        "    assert new_identity()\n"
                    ),
                ),
            ),
        ),
        policy=SimpleNamespace(policy_id="policy:identity"),
        receipt=SimpleNamespace(receipt_id="receipt:identity"),
    )
    compact = TodoImplementationDaemon._compact_proposal_validation(
        proposal_validation
    )
    diagnostic = daemon._record_failed_attempt_retry_context(
        task,
        returncode=78,
        validation_result={
            "attempted": False,
            "passed": False,
            "returncode": 78,
            "reason": "proposal_gate_failed",
            "proposal_gate": compact,
        },
    )

    assert diagnostic is not None
    assert len(diagnostic.changed_symbols) == 256
    assert "test_stable_identity" in diagnostic.changed_symbols
    assert secret_symbol not in diagnostic.changed_symbols
    prompt = daemon._build_implementation_prompt(task, attempt=2)
    assert "test_stable_identity" in prompt
    assert secret_symbol not in prompt


@pytest.mark.parametrize(
    "mutation",
    ("tampered_receipt", "cross_task", "cross_commit"),
)
def test_post_merge_denial_rebinding_fails_closed_and_suppresses_pending(
    post_merge_denial_case_factory,
    mutation,
):
    case = post_merge_denial_case_factory()
    prefix = [
        event
        for event in case.daemon._iter_events()
        if event["type"]
        in {"implementation_started", "implementation_finished"}
    ]
    assert len(prefix) == 2
    state_dir = case.repo / "state" / f"rebinding-{mutation}"
    daemon = TodoImplementationDaemon(
        todo_path=case.todo_path,
        state_path=state_dir / "task_state.json",
        strategy_path=state_dir / "strategy.json",
        events_path=state_dir / "events.jsonl",
        repo_root=case.repo,
        task_header_prefix="## REV-",
        merge_queue=case.queue,
        worktree_submodule_paths=[],
    )
    for implementation_event in prefix:
        event_type, event_payload = _post_merge_test_event_payload(
            implementation_event
        )
        daemon._record_event(
            event_type,
            event_payload,
            enrich=False,
        )

    denial_type, denial_payload = _post_merge_test_event_payload(
        case.denial
    )
    pending_type, pending_payload = _post_merge_test_event_payload(
        case.pending
    )
    if mutation == "tampered_receipt":
        denial_payload["review_receipt"]["review_response"][
            "findings"
        ][0]["summary"] = "mutated after receipt issuance"
    elif mutation == "cross_task":
        denial_payload["task_id"] = "RETRY-999"
    else:
        denial_payload["implementation_commit"] = case.baseline
    daemon._record_event(
        denial_type,
        denial_payload,
        enrich=False,
    )
    daemon._record_event(
        pending_type,
        pending_payload,
        enrich=False,
    )

    assert daemon._post_merge_review_corrections_by_task() == {}
    assert (
        daemon._post_merge_review_correction_for_task(
            case.task.task_id
        )
        is None
    )
    assert daemon._post_merge_review_feedback_for_attempt(
        case.task,
        2,
    ) == ""
    assert daemon._failed_merge_candidates() == []


def test_completed_queue_request_rehydrates_exact_scope_adjudication(
    tmp_path,
):
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    _git(repo, "checkout", "-b", "main")
    todo_path = repo / "todo.md"
    todo_path.write_text(
        """## REF-050 Recover scope authorization

- Status: todo
- Completion: manual
- Priority: P0
- Track: ops
- Outputs: declared.txt
- Validation: python -m pytest tests/test_contract.py -q
""",
        encoding="utf-8",
    )
    _git(repo, "add", "todo.md")
    _git(repo, "commit", "-m", "seed task")
    baseline = _git(repo, "rev-parse", "HEAD")
    state_dir = repo / "state"
    daemon = TodoImplementationDaemon(
        todo_path=todo_path,
        state_path=state_dir / "task_state.json",
        strategy_path=state_dir / "strategy.json",
        events_path=state_dir / "events.jsonl",
        repo_root=repo,
        task_header_prefix="REF-",
        worktree_submodule_paths=[],
    )
    task = daemon._load_tasks()[0]
    identity = daemon._identity_for_task(task)
    branch = "implementation/ref-050-attempt-3"
    expected_paths = ["declared.txt", "tests/test_contract.py"]
    (repo / "declared.txt").write_text(
        "declared implementation\n",
        encoding="utf-8",
    )
    (repo / "tests").mkdir()
    (repo / "tests/test_contract.py").write_text(
        "def test_contract():\n    assert True\n",
        encoding="utf-8",
    )
    _git(repo, "add", "declared.txt", "tests/test_contract.py")
    _git(repo, "commit", "-m", "REF-050 implementation")
    implementation_commit = _git(repo, "rev-parse", "HEAD")
    proposal_id = "proposal:ref-050"
    policy_id = "policy:ref-050-expanded"
    scope_receipt = ScopeAdjudicationReceipt(
        task_id=task.task_id,
        proposal_id=proposal_id,
        initial_policy_id="policy:ref-050-initial",
        repository_id=daemon._proposal_repository_id(repo),
        repository_tree_id=baseline,
        baseline_id=baseline,
        original_scope_paths=tuple(task.outputs),
        candidate_paths=tuple(expected_paths),
        initial_finding_codes=("path_outside_scope",),
        decisions=(
            ScopePathDecision(
                path="tests/test_contract.py",
                verdict=ScopeExpansionVerdict.JUSTIFIED,
                reason_codes=(
                    ScopeExpansionReason.EXPLICIT_VALIDATION_TARGET,
                ),
            ),
        ),
    ).bind_authorized_policy(policy_id)
    legacy_scope = compact_scope_adjudication(scope_receipt)
    proposal_gate = {
        "accepted": True,
        "proposal_id": proposal_id,
        "policy_id": policy_id,
        "receipt_id": "proposal-receipt:ref-050",
        "repository_tree_id": baseline,
        "changed_paths": expected_paths,
    }
    validation_proof = {
        "passed": True,
        "selection": {"scope": "pre_merge"},
        "proposal_gate": proposal_gate,
        "scope_adjudication": legacy_scope,
    }
    daemon._record_event(
        "implementation_finished",
        {
            "task_id": task.task_id,
            "canonical_task_key": identity.canonical_task_key,
            "canonical_task_cid": identity.canonical_task_cid,
            "attempt": 3,
            "branch": branch,
            "baseline_ref": baseline,
            "implementation_commit": implementation_commit,
            "returncode": 0,
            "validation_result": {
                "passed": True,
                "proposal_gate": proposal_gate,
                "scope_adjudication": legacy_scope,
            },
        },
    )
    assert daemon.merge_queue is not None
    request = daemon.merge_queue.enqueue(
        branch_name=branch,
        task_id=task.task_id,
        priority="P0",
        attempt=1,
        metadata={
            "target_binding_schema": MERGE_TARGET_BINDING_SCHEMA,
            "target_repository_id": daemon.merge_target_repository_id,
            "target_branch": daemon.resolved_merge_target_branch,
            "baseline_ref": baseline,
            "implementation_attempt": 3,
            "repo_root": str(repo),
            "state_path": str(daemon.state_path),
            "events_path": str(daemon.events_path),
            "validation_proof": validation_proof,
        },
        commit_sha=implementation_commit,
        canonical_task_id=identity.canonical_task_cid,
        canonical_task_key=identity.canonical_task_key,
        target_repository_id=daemon.merge_target_repository_id,
        target_branch=daemon.resolved_merge_target_branch,
    )
    claimed = daemon.merge_queue.dequeue("scope-recovery-test")
    assert claimed is not None
    daemon.merge_queue.complete(claimed)

    paths, adjudication_id, error = (
        daemon._recover_completed_request_scope_adjudication(
            request_id=request.request_id,
            task=task,
            queue_attempt=1,
            implementation_attempt=3,
            branch=branch,
            implementation_commit=implementation_commit,
            baseline_ref=baseline,
            expected_changed_paths=expected_paths,
        )
    )
    assert error == ""
    assert paths == ["tests/test_contract.py"]
    assert adjudication_id
    finished_event, event_error = (
        daemon._scope_implementation_finished_event(
            task=task,
            implementation_attempt=3,
            branch=branch,
            implementation_commit=implementation_commit,
            baseline_ref=baseline,
            implementation_events_path=daemon.events_path,
            provenance=None,
        )
    )
    assert event_error == ""
    assert finished_event is not None
    forged_validation_proof = json.loads(json.dumps(validation_proof))
    forged_validation_proof["scope_adjudication"]["decisions"][0][
        "reason_codes"
    ] = [ScopeExpansionReason.CANDIDATE_IMPORTS_DECLARED_PATH.value]
    _paths, _adjudication_id, error = (
        daemon._verified_scope_adjudication_projection(
            forged_validation_proof,
            task=task,
            baseline_ref=baseline,
            implementation_commit=implementation_commit,
            expected_changed_paths=expected_paths,
            finished_event=finished_event,
        )
    )
    assert error == "scope_adjudication_queue_event_mismatch"

    replay_path = state_dir / "unmanifested-replay.jsonl"
    replay_path.write_text(
        json.dumps(finished_event, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    replayed_event, replay_error = (
        daemon._scope_implementation_finished_event(
            task=task,
            implementation_attempt=3,
            branch=branch,
            implementation_commit=implementation_commit,
            baseline_ref=baseline,
            implementation_events_path=replay_path,
            provenance=None,
        )
    )
    assert replayed_event is None
    assert replay_error == "scope_adjudication_event_missing"

    _paths, _adjudication_id, error = (
        daemon._recover_completed_request_scope_adjudication(
            request_id=request.request_id,
            task=task,
            queue_attempt=1,
            implementation_attempt=3,
            branch="implementation/forged",
            implementation_commit=implementation_commit,
            baseline_ref=baseline,
            expected_changed_paths=expected_paths,
        )
    )
    assert error == "scope_adjudication_request_binding_mismatch"


