def _seed_parent_with_divergent_gitlinks(
    tmp_path: Path,
    *,
    content_conflict: bool = False,
) -> tuple[Path, Path, str, str, str]:
    repo, submodule = _seed_parent_with_submodule(tmp_path)
    base_submodule = _git(submodule, "rev-parse", "HEAD")
    base_parent = _git(repo, "rev-parse", "HEAD")

    if content_conflict:
        (submodule / "child.txt").write_text("ours\n", encoding="utf-8")
        _git(submodule, "commit", "-am", "ours child change")
    else:
        (submodule / "ours.txt").write_text("ours\n", encoding="utf-8")
        _git(submodule, "add", "ours.txt")
        _git(submodule, "commit", "-m", "ours child change")
    ours = _git(submodule, "rev-parse", "HEAD")
    _git(repo, "add", "libs/child")
    _git(repo, "commit", "-m", "advance child on main")

    _git(submodule, "checkout", "-b", "child-side", base_submodule)
    if content_conflict:
        (submodule / "child.txt").write_text("theirs\n", encoding="utf-8")
        _git(submodule, "commit", "-am", "theirs child change")
    else:
        (submodule / "theirs.txt").write_text("theirs\n", encoding="utf-8")
        _git(submodule, "add", "theirs.txt")
        _git(submodule, "commit", "-m", "theirs child change")
    theirs = _git(submodule, "rev-parse", "HEAD")

    _git(repo, "checkout", "-b", "implementation/auto-116", base_parent)
    _git(repo, "add", "libs/child")
    _git(repo, "commit", "-m", "AUTO-116: advance child on implementation")
    _git(repo, "checkout", "main")
    _git(submodule, "checkout", "main")
    assert _git(submodule, "rev-parse", "HEAD") == ours
    assert _git(repo, "status", "--porcelain") == ""
    return repo, submodule, base_submodule, ours, theirs


def test_implementation_daemon_submodule_gitlink_reconciliation_uses_verified_recovery_ref(tmp_path):
    repo, submodule, base, ours, theirs = _seed_parent_with_divergent_gitlinks(tmp_path)
    state_dir = tmp_path / "supervisor-state"
    daemon = TodoImplementationDaemon(
        todo_path=repo / "todo.md",
        state_path=state_dir / "task_state.json",
        strategy_path=state_dir / "strategy.json",
        events_path=state_dir / "events.jsonl",
        repo_root=repo,
        worktree_submodule_paths=["libs/child"],
    )

    result = daemon._merge_branch_to_main(
        "implementation/auto-116",
        PortalTask(
            task_id="AUTO-116",
            title="Reconcile divergent gitlinks",
            status="todo",
            completion="manual",
            priority="P0",
            track="ops",
        ),
        1,
    )

    assert result["merged"] is True
    repair = result["submodule_conflict_repair"]["repairs"][0]
    selected = repair["selected_commit"]
    assert repair["path"] == "libs/child"
    assert repair["ours_candidate"] == ours
    assert repair["theirs_candidate"] == theirs
    assert repair["reachable_merge_bases"] == [base]
    assert repair["selection_reason"] == "created_deterministic_recovery_ref"
    assert repair["recovery_ref"].startswith("refs/agent-supervisor/submodule-merge-recovery/")
    assert _git(submodule, "merge-base", "--is-ancestor", ours, selected) == ""
    assert _git(submodule, "merge-base", "--is-ancestor", theirs, selected) == ""
    assert _git(submodule, "rev-parse", "HEAD") == ours
    assert _git(repo, "rev-parse", "HEAD:libs/child") == selected

    diagnostic = json.loads((state_dir / "submodule-merge-diagnostics.json").read_text(encoding="utf-8"))
    assert diagnostic["schema_version"] == 1
    assert diagnostic["latest"]["repaired"] is True
    assert diagnostic["latest"]["retryable"] is False
    assert diagnostic["latest"]["conflicts"][0]["selected_commit"] == selected


def test_operator_approved_exact_postimage_wins_over_same_tree_gitlink_recovery(
    tmp_path,
):
    """Model the UIR-002/UIR-010 sibling graph and exact 18cac-style review."""

    repo, submodule = _seed_parent_with_submodule(tmp_path)
    _configure_child_main_in_root_target(repo)
    daemon = _submodule_integration_preflight_daemon(repo, tmp_path)
    task = _submodule_proposal_task("libs/child/child.txt")
    branch_name = "implementation/auto-121-exact-root-gitlink"
    (
        preflight,
        approved_targets,
        root_candidate,
        child_candidate,
    ) = _create_preflight_bound_child_candidate(
        repo,
        submodule,
        daemon,
        task,
        branch_name=branch_name,
    )
    child_baseline = approved_targets["libs/child"][
        "integration_target"
    ]

    # The target root lands an independent child sibling first (82eda-style).
    _git(
        submodule,
        "checkout",
        "-b",
        "already-landed-child-sibling",
        child_baseline,
    )
    (submodule / "already-landed.txt").write_text(
        "independent landed child work\n",
        encoding="utf-8",
    )
    _git(submodule, "add", "already-landed.txt")
    _git(submodule, "commit", "-m", "land independent child sibling")
    landed_sibling = _git(submodule, "rev-parse", "HEAD")
    _git(repo, "add", "libs/child")
    _git(repo, "commit", "-m", "record independently landed child")

    # Operator review approves the exact merge with candidate-first parents
    # (18cac-style). A reverse-parent commit has the same tree but a different
    # identity (fac44a-style) and is already present at the recovery ref.
    _git(
        submodule,
        "checkout",
        "-b",
        "operator-reviewed-exact",
        child_candidate,
    )
    _git(
        submodule,
        "merge",
        "--no-ff",
        "--no-edit",
        landed_sibling,
    )
    approved_exact = _git(submodule, "rev-parse", "HEAD")
    approved_tree = _git(
        submodule,
        "rev-parse",
        f"{approved_exact}^{{tree}}",
    )
    same_tree_alternative = _git(
        submodule,
        "commit-tree",
        approved_tree,
        "-p",
        landed_sibling,
        "-p",
        child_candidate,
        "-m",
        "same-tree deterministic alternative",
    )
    assert approved_exact != same_tree_alternative
    assert _git(
        submodule,
        "rev-parse",
        f"{same_tree_alternative}^{{tree}}",
    ) == approved_tree
    assert _git(
        submodule,
        "rev-list",
        "--parents",
        "-n",
        "1",
        approved_exact,
    ).split()[1:] == [child_candidate, landed_sibling]
    assert _git(
        submodule,
        "rev-list",
        "--parents",
        "-n",
        "1",
        same_tree_alternative,
    ).split()[1:] == [landed_sibling, child_candidate]

    _git(
        submodule,
        "update-ref",
        "refs/heads/main",
        approved_exact,
        child_baseline,
    )
    recovery_ref = daemon._submodule_recovery_ref(
        "libs/child",
        landed_sibling,
        child_candidate,
    )
    _git(
        submodule,
        "update-ref",
        recovery_ref,
        same_tree_alternative,
    )
    approved_targets["libs/child"][
        "operator_approved_integrated_target"
    ] = approved_exact
    _git(submodule, "checkout", "--detach", landed_sibling)
    assert _git(repo, "status", "--porcelain") == ""

    result = daemon._merge_branch_to_main(
        branch_name,
        task,
        1,
        baseline_ref=str(preflight["root_target_commit"]),
        changed_submodule_paths={"libs/child"},
        approved_submodule_integration_targets=approved_targets,
        immutable_candidate_commit=root_candidate,
    )

    assert result["merged"] is True
    repair = result["submodule_conflict_repair"]["repairs"][0]
    assert repair["ours_candidate"] == landed_sibling
    assert repair["theirs_candidate"] == child_candidate
    assert repair["selected_commit"] == approved_exact
    assert repair["selected_commit"] != same_tree_alternative
    assert repair["selection_reason"] == (
        "operator_approved_exact_integrated_postimage"
    )
    assert repair["operator_approved_postimage_check"]["passed"] is True
    assert result["merged_gitlink_recording"][
        "operator_postimage_checks"
    ]["libs/child"]["passed"] is True
    assert _git(repo, "rev-parse", "HEAD:libs/child") == approved_exact
    assert _git(submodule, "rev-parse", "HEAD") == approved_exact
    assert _git(repo, "status", "--porcelain") == ""


