    (submodule / "unrelated.txt").write_text("unrelated task work\n", encoding="utf-8")
    _git(submodule, "add", "unrelated.txt")
    _git(submodule, "commit", "-m", "unrelated child task")
    unrelated_commit = _git(submodule, "rev-parse", "HEAD")
