def test_implementation_supervisor_graces_recent_worker_disappearance(
    tmp_path,
    monkeypatch,
):
    repo = tmp_path / "repo"
    repo.mkdir()
    supervisor = TodoImplementationSupervisor(
        TodoSupervisorConfig(
            todo_path=repo / "todo.md",
            state_path=repo / "state.json",
            strategy_path=repo / "strategy.json",
            events_path=repo / "events.jsonl",
            state_dir=repo / "state",
            implementation_log_stall_seconds=60,
        )
    )
    state = TodoTaskState(
        active_task_id="AUTO-001",
        active_phase="implementing",
        active_phase_started_at="2000-01-01T00:00:00+00:00",
    )
    clock = [100.0]
    worker_count = [1]

    def fake_worker_status(*_args, **_kwargs):
        count = worker_count[0]
        return {
            "required": True,
            "phase": "implementing",
            "phase_age_seconds": 1800.0,
            "threshold_seconds": 60.0,
            "active_worker_pids": [1234] if count else [],
            "active_worker_count": count,
            "descendant_count": count,
            "stalled_without_active_worker": not bool(count),
        }

    monkeypatch.setattr(
        "ipfs_accelerate_py.agent_supervisor.todo_daemon."
        "implementation_supervisor.worktree_phase_worker_status",
        fake_worker_status,
    )
    monkeypatch.setattr(
        "ipfs_accelerate_py.agent_supervisor.todo_daemon."
        "implementation_supervisor.time.monotonic",
        lambda: clock[0],
    )

    assert supervisor._worktree_phase_without_worker_reason(state, now_ts=time.time()) == ""
    worker_count[0] = 0
    clock[0] = 110.0
    assert supervisor._worktree_phase_without_worker_reason(state, now_ts=time.time()) == ""
    clock[0] = 161.0
    reason = supervisor._worktree_phase_without_worker_reason(state, now_ts=time.time())

    assert "no active worker for 61.0s" in reason
    events = [
        json.loads(line)
        for line in (repo / "events.jsonl").read_text(encoding="utf-8").splitlines()
    ]
    assert events[-1]["worker_status"]["worker_absence_age_seconds"] == 61.0


def test_implementation_supervisor_repairs_stale_merge_resolver_without_worker(tmp_path):
    repo = tmp_path / "repo"
    repo.mkdir()
    state_dir = repo / "state"
    state_dir.mkdir()
    state_path = state_dir / "task_state.json"
    now = datetime.now(timezone.utc)
    old = now.replace(year=2000)
    TodoTaskState(
        active_task_id="AUTO-001",
        active_task_title="Stale merge resolver",
        active_task_track="ops",
        active_task_started_at=old.isoformat(),
        active_attempt=1,
        active_phase="merge_resolver",
        active_phase_started_at=old.isoformat(),
        active_phase_detail="merge_conflict",
        implementation_in_progress=True,
        last_implementation_task_id="AUTO-001",
        last_implementation_started_at=old.isoformat(),
        heartbeat_at=now.isoformat(),
        last_progress_at=now.isoformat(),
        ready_count=1,
    ).save(state_path)
    config = TodoSupervisorConfig(
        todo_path=repo / "todo.md",
        state_path=state_path,
        strategy_path=state_dir / "strategy.json",
        events_path=state_dir / "supervisor_events.jsonl",
        state_dir=state_dir,
        repo_root=repo,
        check_interval=1,
        stale_seconds=3600,
    )

    result = TodoImplementationSupervisor(config).run_once()

    assert result["stuck"] is True
    assert "merge_resolver stalled" in result["reason"]
    assert result["state_repair"]["repaired"] is True
    repaired_state = TodoTaskState.load(state_path)
    assert repaired_state.active_task_id == ""
    events = [json.loads(line) for line in (state_dir / "supervisor_events.jsonl").read_text(encoding="utf-8").splitlines()]
    assert any(event["type"] == "worktree_phase_without_worker" for event in events)


def test_implementation_supervisor_repairs_generated_dirty_after_stuck_recovery(
    monkeypatch, tmp_path
):
    repo = tmp_path / "repo"
    repo.mkdir()
    state_dir = repo / "state"
    state_dir.mkdir()
    state_path = state_dir / "task_state.json"
    now = datetime.now(timezone.utc)
    old = now.replace(year=2000)
    TodoTaskState(
        active_task_id="AUTO-001",
        active_task_title="Stale merge resolver",
        active_task_track="ops",
        active_task_started_at=old.isoformat(),
        active_attempt=1,
        active_phase="merge_resolver",
        active_phase_started_at=old.isoformat(),
        active_phase_detail="merge_conflict",
        implementation_in_progress=True,
        last_implementation_task_id="AUTO-001",
        last_implementation_started_at=old.isoformat(),
        heartbeat_at=now.isoformat(),
        last_progress_at=now.isoformat(),
        ready_count=1,
    ).save(state_path)
    supervisor = TodoImplementationSupervisor(
        TodoSupervisorConfig(
            todo_path=repo / "todo.md",
            state_path=state_path,
            strategy_path=state_dir / "strategy.json",
            events_path=state_dir / "supervisor_events.jsonl",
            state_dir=state_dir,
            repo_root=repo,
            check_interval=1,
            stale_seconds=3600,
            generated_dirty_repair_enabled=True,
        )
    )
    repair_calls: list[int] = []

    def fake_generated_repair() -> dict[str, object]:
        repair_calls.append(len(repair_calls) + 1)
        return {
            "attempted": True,
            "selected_path_count": 1,
            "committed_count": 1,
            "call_index": repair_calls[-1],
        }

    monkeypatch.setattr(supervisor, "repair_generated_dirty_checkouts", fake_generated_repair)

    result = supervisor.run_once()

    assert result["stuck"] is True
    assert repair_calls == [1, 2]
    assert result["generated_dirty_repair"]["call_index"] == 1
    assert result["post_stuck_generated_dirty_repair"]["call_index"] == 2


def test_generated_dirty_repair_owns_checkout_lock_and_defers_foreign_owner(
    tmp_path,
) -> None:
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    _git(repo, "checkout", "-b", "main")
    todo_path = repo / "docs" / "generated.todo.md"
    todo_path.parent.mkdir()
    todo_path.write_text("# Generated board\n", encoding="utf-8")
    _git(repo, "add", "docs/generated.todo.md")
    _git(
        repo,
        "-c",
        "user.name=Test User",
        "-c",
        "user.email=test@example.invalid",
        "commit",
        "-m",
        "seed generated board",
    )

    state_dir = tmp_path / "state"
    supervisor = TodoImplementationSupervisor(
        TodoSupervisorConfig(
            todo_path=todo_path,
            state_path=state_dir / "task_state.json",
            strategy_path=state_dir / "strategy.json",
            events_path=state_dir / "events.jsonl",
            state_dir=state_dir,
            repo_root=repo,
            generated_dirty_repair_enabled=True,
            generated_dirty_repair_commit_subject=(
                "Agent: persist generated board"
            ),
            generated_dirty_repair_paths=(todo_path,),
            implementation_protected_paths=("docs/generated.todo.md",),
        )
    )

    todo_path.write_text(
        "# Generated board\n\n## AUTO-001 Repair\n",
        encoding="utf-8",
    )
    repaired = supervisor.repair_generated_dirty_checkouts()

    assert repaired["committed_count"] == 1
    assert repaired["selected_path_count"] == 1
    assert not checkout_mutation_lock_path(repo).exists()
    assert _git(repo, "log", "-1", "--pretty=%ae") == (
        BACKLOG_REFINERY_AUTHOR_EMAIL
    )
    assert _git(repo, "log", "-1", "--pretty=%s").endswith(
        GENERATED_PROTECTED_BOARD_COMMIT_MARKER
    )
    assert _git(repo, "status", "--porcelain", "--untracked-files=all") == ""

    todo_path.write_text(
        "# Generated board\n\n## AUTO-002 Deferred\n",
        encoding="utf-8",
    )
    lock_path = checkout_mutation_lock_path(repo)
    lock_path.write_text(
        json.dumps(
            {
                "kind": "merge",
                "pid": os.getpid(),
                "owner_script": "",
                "repo_root": str(repo.resolve()),
                "operation": "foreign_checkout_mutation",
            }
        ),
        encoding="utf-8",
    )
    deferred = supervisor.repair_generated_dirty_checkouts()

    assert deferred["attempted"] is False
    assert deferred["reason"] == "checkout_mutation_lock_unavailable"
    assert "docs/generated.todo.md" in _git(repo, "status", "--short")


